def split_bill_evenly(total_amount: float, num_people: int) -> list[float]:
    # Convert to integer cents to avoid floating-point issues.
    total_cents = int(round(total_amount * 100))
    base_cents = total_cents // num_people
    remainder = total_cents % num_people

    # Build the list: first `remainder` people get one extra cent.
    result = []
    for i in range(num_people):
        if i < remainder:
            result.append(round(base_cents + 1, 2) / 100)
        else:
            result.append(round(base_cents, 2) / 100)
    return result

