def split_bill_evenly(total_amount: float, num_people: int) -> list[float]:
    if num_people == 0:
        raise ZeroDivisionError("num_people must be non-zero")
    if num_people < 0:
        return []

    # Convert to integer cents to avoid floating‑point pitfalls
    total_cents = round(total_amount * 100)

    base, remainder = divmod(total_cents, num_people)

    # remainder people get one extra cent
    # (first `remainder` people)
    result = []
    for i in range(num_people):
        if i < remainder:
            result.append(base + 1)
        else:
            result.append(base)

    # Convert back to dollars (float with two decimal places)
    return [c / 100.0 for c in result]
